// Pattern from CreateItem.cs:
public class CreateWeighbridge
{
    public record Command(
        string Code,
        string Name,
        decimal MaxCapacityKg,
        IntegrationMode IntegrationMode,
        Guid WarehouseId,
        bool IsActive = true
    ) : ICommand<Guid>;

    public class CommandValidator : AbstractValidator<Command>
    {
        public CommandValidator(ILocalizationService localizationService)
        {
            RuleFor(x => x.Code).NotEmpty().WithName(localizationService.GetPropertyName("Weighbridge.Code"))
                .MaximumLength(WeighbridgeConsts.ColumnMaxLengths.Code).WithName(localizationService.GetPropertyName("Weighbridge.Code"));
            RuleFor(x => x.Name).NotEmpty().WithName(localizationService.GetPropertyName("Weighbridge.Name"))
                .MaximumLength(WeighbridgeConsts.ColumnMaxLengths.Name).WithName(localizationService.GetPropertyName("Weighbridge.Name"));
            RuleFor(x => x.MaxCapacityKg).GreaterThan(0).WithName(localizationService.GetPropertyName("Weighbridge.MaxCapacityKg"));
            RuleFor(x => x.WarehouseId).NotEmpty().WithName(localizationService.GetPropertyName("Weighbridge.WarehouseId"));
        }
    }

    public class CommandHandler(
        IAppDbContext context,
        ILogger<CommandHandler> logger) : ICommandHandler<Command, Guid>
    {
        public async Task<Guid> HandleAsync(Command command, CancellationToken cancellationToken = default)
        {
            if (await context.Weighbridges.AnyAsync(x => x.Code.ToLower() == command.Code.ToLower(), cancellationToken))
                throw BusinessRule.Weighbridges.CodeAlreadyExists.ToBusinessException([command.Code]);

            var entity = new Weighbridge
            {
                Code = command.Code,
                Name = command.Name,
                MaxCapacityKg = command.MaxCapacityKg,
                IntegrationMode = command.IntegrationMode,
                WarehouseId = command.WarehouseId,
                IsActive = command.IsActive
            };

            context.Weighbridges.Add(entity);
            await context.SaveChangesAsync(cancellationToken);
            logger.LogInformation("Weighbridge {Code} created with ID {Id}", entity.Code, entity.Id);
            return entity.Id;
        }
    }
}

