public sealed class WeighbridgesController(IDispatcher dispatcher) : ControllerBase
{
    [HttpGet("lookup")]
    [ProducesResponseType(typeof(ApiResult<List<LookupDto>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> Lookup([FromQuery] Guid? warehouseId = null, [FromQuery] string? search = null, CancellationToken ct = default)
    {
        var result = await dispatcher.QueryAsync(new GetWeighbridgeLookup.Query { WarehouseId = warehouseId, Search = search }, ct);
        return Ok(ApiResult<List<LookupDto>>.Success(result));
    }

    [HttpPost("search")]
    public async Task<IActionResult> Search([FromBody] GetWeighbridgeList.Query query, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(query, ct);
        return Ok(ApiResult<DynamicGridResult>.Success(result));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById([FromRoute] Guid id, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetWeighbridgeById.Query(id), ct);
        if (result == null) return NotFound();
        return Ok(ApiResult<WeighbridgeDto>.Success(result));
    }

    [HttpPost]
    [ProducesResponseType(typeof(ApiResult<Guid>), StatusCodes.Status201Created)]
    public async Task<IActionResult> Create([FromBody] CreateWeighbridge.Command command, CancellationToken ct)
    {
        var id = await dispatcher.DispatchAsync(command, ct);
        return StatusCode(StatusCodes.Status201Created, ApiResult<Guid>.Success(id));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] UpdateWeighbridge.Command command, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(command with { Id = id }, ct);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(new DeleteWeighbridge.Command(id), ct);
        return NoContent();
    }
}

