// BackgroundService pattern for MaterializationWorker:
public class MaterializationWorker(
    IServiceProvider serviceProvider,
    ILogger<MaterializationWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = serviceProvider.CreateScope();
                var context = scope.ServiceProvider.GetRequiredService<IAppDbContext>();
                // Poll outbox for pending events
                var pendingEvents = await context.InventoryEventOutboxes
                    .Where(x => x.Status == "Pending")
                    .OrderBy(x => x.Id)
                    .Take(100)
                    .ToListAsync(stoppingToken);

                foreach (var evt in pendingEvents)
                {
                    await ProcessEventAsync(context, evt, stoppingToken);
                }
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Materialization worker error");
            }
            await Task.Delay(500, stoppingToken); // Poll interval
        }
    }
}

