// SHA-256 lot hash with configurable attributes:
public async Task<string> ComputeLotHashAsync(Guid itemId, Guid ownerId, Dictionary<string, string?> attrs, CancellationToken ct)
{
    var hashAttrs = await _systemConfigService.GetAsync<List<string>>("lot_hash_attrs", ct)
        ?? new List<string> { "item_id", "owner_id", "lot_attr_01", "lot_attr_03", "lot_attr_08", "lot_attr_09" };

    var parts = new List<string> { _currentUser.TenantId.ToString()! };
    foreach (var attr in hashAttrs)
    {
        var val = attr switch
        {
            "item_id" => itemId.ToString(),
            "owner_id" => ownerId.ToString(),
            _ => attrs.GetValueOrDefault(attr)
        };
        parts.Add(val ?? string.Empty);
    }

    var input = string.Join("|", parts);
    var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(input));
    return Convert.ToHexStringLower(bytes);
}

